import { required, email, maxLength, minLength } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  fields: [
    {
      id: 'account',
      type: 'account',
      className: 'mb-3',
      validators: { required, email },
      label: 'starterLayout.signUp.email',
      icon: 'mdi-at',
      autofocus: true,
    },
    {
      id: 'password',
      type: 'password',
      className: 'mb-3',
      validators: {
        required,
        maxLength: maxLength(30),
        minLength: minLength(4),
      },
    },
  ],
  id: 'signup-form',
  onSubmit: () => methods.submit(),
})

export default setConfig
